sys_script_include.script:
var SchemaUtil = Class.create();
SchemaUtil.prototype = {
    initialize: function() {
        this.registry = new SchemaRegistry(); // centralized schema store
		this.logger = new PanoramaLogger("x_835786_firewall.PanoramaAdapter.debug", "SchemaUtil");
    },

    /**
     * Retrieves the schema from the registry and maps the payload into normalized records.
     * @param {string} schemaKey - e.g. 'application_data'
     * @param {object} payload - raw JSON response from Panorama
     * @returns {object} { records: [...] }
	 * 
     * The below function uses the schema map to determine which keys and values we extract from the JSON received from the REST request. To add additional values, add them to the SchemaRegistry. You must also add corresponding table columns with the same 'name' value to corresponding staging and target tables and Transform map.
     *
     *
     */
    parseResponse: function(payload, schemaMap) {
		this.logger.debug("Starting parseResponse with schema: " + JSON.stringify(Object.keys(schemaMap)));
        var rawEntries = this._extractEntries(payload);
		this.logger.debug("Extracted " + rawEntries.length + " entries from payload.");
        var map = schemaMap;
        var results = [];

        for (var i = 0; i < rawEntries.length; i++) {
            var entry = rawEntries[i];
            var record = {};

            for (var targetKey in map) {
                if (!map.hasOwnProperty(targetKey)) continue;
                var path = map[targetKey];
                var value = this._resolvePath(entry, path);
                record[targetKey] = this._normalizeValue(value);
            }

            results.push(record);
			this.logger.debug("parseResponse completed. Total records built: " + results.length);
        }

        return {
            records: results
        };
    },

    /**
     * Pulls the relevant node in the Panorama response (e.g. result.entry[])
     */
    _extractEntries: function(payload) {
        if (!payload) {
			this.logger.debug("_extractEntries: payload was empty.");
			return [];
		} 

        if (payload.result && payload.result.entry) {
            var entries = Array.isArray(payload.result.entry) ? payload.result.entry : [payload.result.entry];
			this.logger.debug("_extractEntries: found " + entries.length + " entries.");
			return entries;
		}
		this.logger.debug("_extractEntries: no result.entry found in payload.");
		return [];
    },

    _dedupeByKey: function(records, key) {
        var seen = {};
        return records.filter(function(rec) {
            var val = rec[key];
            if (!val) return true; // keep if key not defined
            if (seen[val]) return false; // drop dup
            seen[val] = true;
            return true;
        });
    },

    _resolvePath: function(obj, path) {
        if (!obj || !path) return null;
        var parts = path.split(".");
        var current = obj;

        for (var i = 0; i < parts.length; i++) {
            if (current == null) {
				this.logger.debug("_resolvePath: null encountered at part '" + parts[i] + "' for path '" + path + "'");
				return null;
			}
            current = current[parts[i]];
        }

        return current;
    },
    /**
    Panorama uses {member : []} when multiple values are present for a property so we must normalize these values into strings before we pass them into the records object for the Import Set API.

	*normalizeValue function serves to stringify multiple values inside nested JSON. Specifically, we retrieve the 'member' property, like the 'default.port.member' and 'list.member' from Panorama application profiles and url categories, respectively.
    **/
    _normalizeValue: function(value) {
		this.logger.debug("_normalizeValue: input=" + JSON.stringify(value));
        if (value && typeof value === "object" && value.member) {
            var arr = Array.isArray(value.member) ? value.member : [value.member];
            return arr.join(",");
        }
        if (Array.isArray(value)) return value.join(",");
        return value || null;
    },

    type: 'SchemaUtil'
};
